import{supabase as m}from"./supabase-DUkCiNAm.js";/* empty css              */document.getElementById("login-form").addEventListener("submit",async e=>{e.preventDefault();let a=document.getElementById("email").value.trim();a.includes("@")||(a+="@automatizap.com");const d=document.getElementById("password").value,r=document.getElementById("login-error"),t=document.querySelector(".login-btn");t.textContent="Entrando...",t.disabled=!0,r.style.display="none";const{data:c,error:s}=await m.auth.signInWithPassword({email:a,password:d});if(s){t.textContent="Entrar",t.disabled=!1;let o="Ocorreu um erro ao acessar.";s.message.includes("Invalid login credentials")?o="E-mail ou senha incorretos.":s.message.includes("Email not confirmed")?o="E-mail não confirmado.":o="Erro: "+s.message,r.textContent=o,r.style.display="block";const n=document.querySelector(".login-form-container");n.style.transform="translateX(-10px)",setTimeout(()=>n.style.transform="translateX(10px)",100),setTimeout(()=>n.style.transform="translateX(-10px)",200),setTimeout(()=>n.style.transform="translateX(0)",300)}else window.location.href="index.html"});const i=document.getElementById("togglePassword"),l=document.getElementById("password");i&&l&&i.addEventListener("click",function(){const e=l.getAttribute("type")==="password"?"text":"password";l.setAttribute("type",e),e==="password"?(this.classList.remove("ph-eye-slash"),this.classList.add("ph-eye")):(this.classList.remove("ph-eye"),this.classList.add("ph-eye-slash"))});
